() => {
  // Find the container of the project cards
  const h1 = document.querySelector('h1');
  const parent = h1.parentElement;

  // Find the card container - should be the flex/grid row of cards
  const children = Array.from(parent.children);

  // Get the cards container element
  // Cards seem to be direct children or in a wrapper
  const cards = parent.querySelectorAll('[class]');
  const uniqueClasses = new Set();
  cards.forEach(c => c.className.split(' ').forEach(cls => uniqueClasses.add(cls)));

  return {
    parentTag: parent.tagName,
    parentClass: parent.className,
    parentStyles: window.getComputedStyle(parent).cssText.substring(0, 500),
    childCount: children.length,
    childTags: children.map(c => ({ tag: c.tagName, class: c.className, text: c.textContent.substring(0, 30) })),
    uniqueClasses: Array.from(uniqueClasses)
  };
}

