() => {
  const parent = document.querySelector('h1').parentElement;
  const cardRow = parent.children[1];
  const cards = Array.from(cardRow.children);

  return cards.map((card, i) => {
    const cs = window.getComputedStyle(card);
    const titleDiv = card.children[0];
    const titleCs = window.getComputedStyle(titleDiv);
    return {
      index: i,
      titleText: titleDiv.textContent,
      cardFlex: cs.flex,
      cardMinWidth: cs.minWidth,
      cardWidth: card.offsetWidth + 'px',
      titleWhiteSpace: titleCs.whiteSpace,
      titleOverflow: titleCs.overflow,
      titleTextOverflow: titleCs.textOverflow,
      titleWordBreak: titleCs.wordBreak,
      titleOverflowWrap: titleCs.overflowWrap
    };
  });
}
